-- Метаданные плагина
local PLUGIN = {
    name = "Free Custom Themes",
    description = "Добавляет новые бесплатные темы оформления (Киберпанк, Мята, Магма) в настройки.",
    author = "Modder",
    version = "1.0",
    icon = "https://s.fotora.ru/abc45eae0487e11c.png" -- Указанная вами иконка
}

-- JavaScript код, который будет внедрен в приложение
local js_payload = [[
(function() {
    // Функция для создания HTML-кода бесплатной темы
    function createFreeTheme(name, emoji, bgMain, border, textMain, color1, color2, color3) {
        return `
        <div class="masyka-btn-press custom-free-theme" onclick="applyFakeTheme('${bgMain}')" style="position: relative; width: 90px; padding: 10px 6px; border-radius: 14px; background-color: ${bgMain}; border: 2.5px solid ${border}; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 6px; flex-shrink: 0; transition: border-color 0.25s, transform 0.15s;">
            <div style="width: 44px; height: 44px; border-radius: 12px; background-color: ${color3}; display: flex; align-items: center; justify-content: center; font-size: 22px;">${emoji}</div>
            <div style="display: flex; gap: 3px;">
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${color1}; border: 1px solid rgba(0, 0, 0, 0.08);"></div>
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${color2}; border: 1px solid rgba(0, 0, 0, 0.08);"></div>
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${color3}; border: 1px solid rgba(0, 0, 0, 0.08);"></div>
            </div>
            <div style="font-size: 11px; font-weight: 600; color: ${textMain}; text-align: center;">${name}</div>

            <!-- Вместо цены и кристаллов пишем "Бесплатно" -->
            <div style="margin-top: 2px; display: flex; align-items: center; justify-content: center; gap: 3px; font-size: 11px; font-weight: 800; color: #4CAF50;">
                Бесплатно
            </div>
            <!-- Блок с замком (lucide-lock) удален -->
        </div>`;
    }

    // Генерируем 3 новые темы
    const newThemesHTML = 
        createFreeTheme("Киберпанк", "👾", "rgb(26, 11, 46)", "rgb(0, 255, 255)", "rgb(255, 0, 255)", "rgb(255, 0, 255)", "rgb(0, 255, 255)", "rgb(40, 20, 60)") +
        createFreeTheme("Мята", "🍃", "rgb(235, 250, 240)", "rgb(150, 230, 180)", "rgb(40, 100, 60)", "rgb(40, 200, 100)", "rgb(150, 255, 200)", "rgb(255, 255, 255)") +
        createFreeTheme("Вампир", "🦇", "rgb(30, 10, 10)", "rgb(200, 30, 30)", "rgb(255, 100, 100)", "rgb(200, 0, 0)", "rgb(100, 0, 0)", "rgb(50, 15, 15)");

    // Функция поиска контейнера с темами и добавления наших
    function injectThemes() {
        // Ищем контейнер с прокруткой, в котором лежат темы (ориентируемся по тексту базовых тем)
        let themeContainers = document.querySelectorAll('div[style*="overflow-x: auto"]');

        themeContainers.forEach(container => {
            // Проверяем, что это именно контейнер с темами (там есть тема "Классика" или "Закат")
            if (container.innerHTML.includes('Классика') && !container.hasAttribute('data-custom-themes')) {
                container.setAttribute('data-custom-themes', 'true');
                // Добавляем наши темы в конец списка
                container.insertAdjacentHTML('beforeend', newThemesHTML);
            }
        });
    }

    // Симуляция применения темы (изменяет фон на лету)
    window.applyFakeTheme = function(bgColor) {
        document.body.style.backgroundColor = bgColor;
        let panels = document.querySelectorAll('#root > div > div, .masyka-right-panel > div > div, .masyka-sidebar > div');
        panels.forEach(p => {
            if (p.style.backgroundColor && p.style.backgroundColor.includes('rgb')) {
                p.style.backgroundColor = bgColor;
            }
        });
        // Анимация нажатия (визуальная отдача)
        setTimeout(() => alert('Тема успешно применена!'), 100);
    };

    // Поскольку React-приложение рендерит страницы динамически, 
    // используем MutationObserver или интервал для отслеживания открытия настроек.
    setInterval(injectThemes, 1000);
})();
]]

-- Основная функция инициализации плагина (зависит от API вашего Lua лоадера)
function PLUGIN:onLoad()
    print("[MasykaPlugin] " .. self.name .. " загружен!")

    -- Выполнение JS-инъекции. 
    -- Замените "webview.executeJS" на ту функцию, которая используется в вашем клиенте (например, executeJavaScript, runJS и т.д.)
    if webview and webview.executeJS then
        webview:executeJS(js_payload)
    elseif executeJS then
        executeJS(js_payload)
    else
        print("[MasykaPlugin] Ошибка: Функция выполнения JS не найдена.")
    end
end

return PLUGIN
